//! Local interoperability/security fixtures, not accepted-profile crypto vectors.
//! Certificates are generated by rcgen 0.13.2 in-process, trusted only by these
//! tests, with no system root installation, external DNS or external services.
use futures_util::{SinkExt, StreamExt};
use prost::Message as _;
use rustls::pki_types::{CertificateDer, PrivateKeyDer, PrivatePkcs8KeyDer, ServerName};
use std::{
    sync::{
        atomic::{AtomicUsize, Ordering},
        Arc, OnceLock,
    },
    time::Duration,
};
use syntra_runtime::{
    AuthError, Authenticator, ConnectionConfig, FnHandler, Handler, HandlerOutcome, Initiator,
    Principal,
};
use syntra_sc1_transport::{
    websocket as ws, AuthenticatorFactory, Error, HostHandle, LifecycleStatus, Limits,
    ReconnectConfig, ReconnectingClient,
};
use syntra_secure_channel::{
    generate_server_key, Carrier, ClientConfig, ClientHandshake, Context, FrameDecoder, KeyStore,
    Mode, Secret32, ServerConfig, VerifiedIdentity,
};
use tokio::{
    io::{AsyncReadExt, AsyncWriteExt},
    net::TcpListener,
    task::JoinHandle,
};
use tokio_tungstenite::{
    tungstenite::{
        client::IntoClientRequest, handshake::derive_accept_key, http::HeaderValue, protocol::Role,
        Message,
    },
    WebSocketStream,
};

const CREDENTIAL: &[u8] = b"local-wss-fixture-credential";

struct Certificate {
    der: CertificateDer<'static>,
    key: Vec<u8>,
}
impl Certificate {
    fn private_key(&self) -> PrivateKeyDer<'static> {
        PrivatePkcs8KeyDer::from(self.key.clone()).into()
    }
    fn roots(&self) -> rustls::RootCertStore {
        let mut roots = rustls::RootCertStore::empty();
        roots.add(self.der.clone()).unwrap();
        roots
    }
    fn settings(&self) -> ws::TlsServerSettings {
        ws::TlsServerSettings::new(vec![self.der.clone()], self.private_key()).unwrap()
    }
    fn server_config(
        &self,
        version: &'static rustls::SupportedProtocolVersion,
    ) -> rustls::ServerConfig {
        rustls::ServerConfig::builder_with_provider(Arc::new(
            rustls::crypto::ring::default_provider(),
        ))
        .with_protocol_versions(&[version])
        .unwrap()
        .with_no_client_auth()
        .with_single_cert(vec![self.der.clone()], self.private_key())
        .unwrap()
    }
}
fn certificate() -> &'static Certificate {
    static CERT: OnceLock<Certificate> = OnceLock::new();
    CERT.get_or_init(|| {
        // Deliberately only an IP SAN: localhost is a wrong-hostname negative,
        // although both names connect to the same local listener.
        let generated = rcgen::generate_simple_self_signed(vec!["127.0.0.1".into()]).unwrap();
        Certificate {
            der: generated.cert.der().clone(),
            key: generated.key_pair.serialize_der(),
        }
    })
}
fn limits() -> Limits {
    Limits {
        attempt_timeout: Duration::from_secs(5),
        channel_timeout: Duration::from_secs(3),
        ..Limits::default()
    }
}
struct Store;
impl KeyStore for Store {
    fn lookup(&self, context: &Context) -> Result<Secret32, syntra_secure_channel::Error> {
        if context.handle == [4; 8] && context.epoch == 9 {
            Ok(Secret32::new([3; 32]))
        } else {
            Err(syntra_secure_channel::Error::Authentication)
        }
    }
}
fn configs(mode: Mode) -> (ClientConfig, ServerConfig) {
    let (private_key, public_key) = generate_server_key().unwrap();
    let returning = mode == Mode::Returning;
    let context = Context {
        mode,
        carrier: Carrier::SecureWebSocket,
        server_key_id: 12,
        scope: b"wss/local-fixture".to_vec(),
        handle: if returning { [4; 8] } else { [0; 8] },
        epoch: if returning { 9 } else { 0 },
    };
    (
        ClientConfig {
            context: context.clone(),
            server_public_key: public_key,
            authorization_key: returning.then(|| Secret32::new([3; 32])),
        },
        ServerConfig {
            mode,
            carrier: Carrier::SecureWebSocket,
            server_key_id: 12,
            scope: context.scope,
            private_key,
            store: Some(Arc::new(Store)),
        },
    )
}
struct BoundAuth(VerifiedIdentity);
impl Authenticator for BoundAuth {
    fn authenticate(&self, credential: &[u8]) -> Result<Principal, AuthError> {
        if credential != CREDENTIAL || self.0.context().carrier != Carrier::SecureWebSocket {
            return Err(AuthError::unauthenticated());
        }
        Ok(match self.0.context().mode {
            Mode::Returning => Principal::new("local-device-4"),
            Mode::Bootstrap => Principal::anonymous(),
        })
    }
}
fn factory(calls: Arc<AtomicUsize>) -> Arc<dyn AuthenticatorFactory> {
    Arc::new(
        move |id: &VerifiedIdentity| -> Result<Arc<dyn Authenticator>, AuthError> {
            calls.fetch_add(1, Ordering::SeqCst);
            Ok(Arc::new(BoundAuth(id.clone())))
        },
    )
}
fn echo() -> Arc<dyn Handler> {
    Arc::new(FnHandler(|_, payload, _| async move {
        HandlerOutcome::Payload(payload)
    }))
}
async fn listener() -> (TcpListener, String) {
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let url = format!(
        "wss://{}{}",
        listener.local_addr().unwrap(),
        ws::ENDPOINT_PATH
    );
    (listener, url)
}
fn serve(
    listener: TcpListener,
    security: ServerConfig,
    calls: Arc<AtomicUsize>,
) -> JoinHandle<Result<HostHandle, Error>> {
    tokio::spawn(async move {
        let (stream, _) = listener.accept().await.unwrap();
        ws::accept_tls_stream(
            stream,
            &certificate().settings(),
            &security,
            factory(calls),
            echo(),
            ConnectionConfig::default(),
            limits(),
        )
        .await
    })
}
async fn dial(
    url: &str,
    config: ClientConfig,
) -> Result<syntra_sc1_transport::ClientHandle, Error> {
    ws::connect_with_roots(
        url,
        certificate().roots(),
        config,
        CREDENTIAL.to_vec(),
        ConnectionConfig::default(),
        limits(),
    )
    .await
}

#[tokio::test]
async fn verified_wss_real_socket_rpc_both_modes() {
    for mode in [Mode::Bootstrap, Mode::Returning] {
        let (listener, url) = listener().await;
        let (client, server) = configs(mode);
        let calls = Arc::new(AtomicUsize::new(0));
        let task = serve(listener, server, calls.clone());
        let client = dial(&url, client).await.unwrap();
        let host = task.await.unwrap().unwrap();
        assert_eq!(host.identity.context().carrier, Carrier::SecureWebSocket);
        assert_eq!(host.identity.context().mode, mode);
        assert_eq!(calls.load(Ordering::SeqCst), 1);
        let payload = vec![5; 200_000];
        assert_eq!(
            client
                .conn
                .call("/test.Service/Echo", payload.clone(), 5000)
                .await
                .unwrap(),
            payload
        );
        client
            .close_gracefully(Duration::from_secs(1))
            .await
            .unwrap();
        host.close().await;
    }
}

#[tokio::test]
async fn reconnecting_client_replaces_real_wss_with_fresh_generation_both_modes() {
    for mode in [Mode::Bootstrap, Mode::Returning] {
        let (listener, url) = listener().await;
        let (template, security) = configs(mode);
        let context = template.context;
        let pin = template.server_public_key;
        let auth_calls = Arc::new(AtomicUsize::new(0));
        let count = auth_calls.clone();
        let executions = Arc::new(AtomicUsize::new(0));
        let seen = executions.clone();
        let (hosts, mut accepted) = tokio::sync::mpsc::channel(2);
        let server = tokio::spawn(async move {
            let handler = Arc::new(FnHandler(move |_, payload, _| {
                seen.fetch_add(1, Ordering::SeqCst);
                async move { HandlerOutcome::Payload(payload) }
            }));
            for _ in 0..2 {
                let (stream, _) = listener.accept().await.unwrap();
                let host = ws::accept_tls_stream(
                    stream,
                    &certificate().settings(),
                    &security,
                    factory(count.clone()),
                    handler.clone(),
                    ConnectionConfig::default(),
                    limits(),
                )
                .await
                .unwrap();
                hosts.send(host).await.unwrap();
            }
        });
        let mut client = ReconnectingClient::new(
            ReconnectConfig {
                attempt_timeout: Duration::from_secs(5),
                reconnect_budget: Duration::from_secs(20),
                max_attempts: 4,
                base_backoff: Duration::from_millis(10),
                max_backoff: Duration::from_millis(100),
                close_timeout: Duration::from_secs(3),
                start_paused: false,
                initial_network_available: true,
            },
            move || {
                let url = url.clone();
                let security = ClientConfig {
                    context: context.clone(),
                    server_public_key: pin,
                    authorization_key: (mode == Mode::Returning).then(|| Secret32::new([3; 32])),
                };
                async move { dial(&url, security).await }
            },
        )
        .unwrap();
        let mut status = client.subscribe_status();
        let mut generations = Vec::new();
        let mut retained_hosts = Vec::new();
        for expected in 1..=2 {
            let ready = tokio::time::timeout(Duration::from_secs(5), async {
                loop {
                    if let LifecycleStatus::CoreReady(ready) = status.snapshot() {
                        if ready.generation == expected {
                            break ready;
                        }
                    }
                    status.changed().await.unwrap();
                }
            })
            .await
            .unwrap();
            generations.push(ready);
            retained_hosts.push(accepted.recv().await.unwrap());
            let result = client
                .call("/test.Service/Echo", vec![expected as u8], 1000)
                .await
                .unwrap();
            assert_eq!(result.generation, expected);
            assert_eq!(result.value, vec![expected as u8]);
            if expected == 1 {
                client.platform_wake();
            }
        }
        assert_ne!(generations[0].connection_id, generations[1].connection_id);
        assert_eq!(auth_calls.load(Ordering::SeqCst), 2);
        assert_eq!(executions.load(Ordering::SeqCst), 2);
        client.close().await.unwrap();
        for host in retained_hosts {
            host.close().await;
        }
        server.await.unwrap();
    }
}

// A raw HTTP peer avoids tungstenite's server response generation hiding token
// lists, duplicate fields, malformed headers or HTTP/WebSocket read-ahead.
async fn raw_upgrade_peer(
    listener: TcpListener,
) -> (
    tokio_rustls::server::TlsStream<tokio::net::TcpStream>,
    String,
) {
    let (stream, _) = listener.accept().await.unwrap();
    let mut tls = tokio_rustls::TlsAcceptor::from(Arc::new(
        certificate().server_config(&rustls::version::TLS13),
    ))
    .accept(stream)
    .await
    .unwrap();
    let mut bytes = Vec::new();
    while !bytes.ends_with(b"\r\n\r\n") {
        assert!(bytes.len() < 8192);
        bytes.push(tls.read_u8().await.unwrap());
    }
    assert!(!bytes
        .windows(CREDENTIAL.len())
        .any(|part| part == CREDENTIAL));
    let mut headers = [httparse::EMPTY_HEADER; 32];
    let mut request = httparse::Request::new(&mut headers);
    assert!(request.parse(&bytes).unwrap().is_complete());
    assert_eq!(request.path, Some(ws::ENDPOINT_PATH));
    assert!(!request.headers.iter().any(|header| {
        ["authorization", "cookie", "sec-websocket-extensions"]
            .iter()
            .any(|name| header.name.eq_ignore_ascii_case(name))
    }));
    let key = request
        .headers
        .iter()
        .find(|header| header.name.eq_ignore_ascii_case("sec-websocket-key"))
        .unwrap()
        .value;
    let accept = derive_accept_key(key);
    (tls, accept)
}

fn raw_upgrade_response(connection: &str) -> String {
    format!(
        "HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\n{connection}\r\nSec-WebSocket-Accept: ACCEPT_KEY\r\nSec-WebSocket-Protocol: {}\r\n\r\n",
        ws::SUBPROTOCOL
    )
}

#[tokio::test]
async fn connection_token_lists_and_repeated_fields_complete_sc1_with_read_ahead() {
    for connection in [
        "Connection: keep-alive, UpGrAdE",
        "Connection: keep-alive\r\ncOnNeCtIoN: \tupgrade",
    ] {
        for tail in [false, true] {
            let (listener, url) = listener().await;
            let (client, server) = configs(Mode::Returning);
            let task = tokio::spawn(async move {
                let (mut tls, accept) = raw_upgrade_peer(listener).await;
                let mut response = raw_upgrade_response(connection).replace("ACCEPT_KEY", &accept);
                if tail {
                    // Nearly 16 KiB of HTTP plus a Ping in the same TLS write.
                    // Only the HTTP bytes count against the Upgrade budget; the
                    // preserved tail must still elicit a Pong below.
                    let padding = 16 * 1024 - 4 - response.len() - "X-Pad: \r\n".len();
                    response.insert_str(
                        response.len() - 2,
                        &format!("X-Pad: {}\r\n", "x".repeat(padding)),
                    );
                    assert_eq!(response.len(), 16 * 1024 - 4);
                }
                let mut wire = response.into_bytes();
                if tail {
                    wire.extend_from_slice(&[0x89, 64]); // unmasked server Ping
                    wire.extend_from_slice(&[7; 64]);
                    assert!(wire.len() > 16 * 1024);
                }
                tls.write_all(&wire).await.unwrap();
                tls.flush().await.unwrap();
                let mut socket = WebSocketStream::from_raw_socket(tls, Role::Server, None).await;
                let Message::Binary(first) = socket.next().await.unwrap().unwrap() else {
                    panic!("expected M1 after valid Upgrade")
                };
                let (mut channel, second) =
                    syntra_secure_channel::respond(&server, &first).unwrap();
                socket.send(Message::Binary(second.into())).await.unwrap();
                let mut pong = false;
                let hello = loop {
                    match socket.next().await.unwrap().unwrap() {
                        Message::Pong(bytes) => {
                            assert!(tail);
                            assert_eq!(bytes.as_ref(), &[7; 64]);
                            pong = true;
                        }
                        Message::Binary(record) => break record,
                        other => panic!("unexpected message {other:?}"),
                    }
                };
                assert_eq!(pong, tail, "coalesced Ping must survive the Upgrade");
                let plaintext = channel.decrypt(&hello).unwrap();
                let mut frames = syntra_secure_channel::FrameDecoder::default();
                let frames = frames.push(&plaintext).unwrap();
                assert_eq!(frames.len(), 1);
                let hello = syntra_core::Frame::decode(frames[0].as_slice()).unwrap();
                let Some(syntra_core::proto::frame::Body::Hello(hello)) = hello.body else {
                    panic!("expected encrypted hello")
                };
                assert_eq!(hello.credential, CREDENTIAL);
                let ready = syntra_core::Frame {
                    version: 1,
                    request_id: 0,
                    body: Some(syntra_core::proto::frame::Body::Ready(
                        syntra_core::ServerReady {
                            connection_id: "raw-upgrade-fixture".into(),
                        },
                    )),
                }
                .encode_to_vec();
                let ready = channel
                    .encrypt(&syntra_secure_channel::frame_plaintext(&ready).unwrap())
                    .unwrap();
                socket.send(Message::Binary(ready.into())).await.unwrap();
                // Retain the peer until the returned client is explicitly closed.
                let _ = tokio::time::timeout(Duration::from_secs(2), socket.next())
                    .await
                    .unwrap();
            });
            let client = dial(&url, client).await.unwrap();
            assert_eq!(client.connection_id, "raw-upgrade-fixture");
            client.close().await;
            task.await.unwrap();
        }
    }
}

#[tokio::test]
async fn invalid_raw_upgrade_responses_never_receive_m1() {
    let valid = raw_upgrade_response("Connection: Upgrade");
    let mut cases = vec![
        (
            "unsolicited compression",
            valid.replace(
                "\r\n\r\n",
                "\r\nSec-WebSocket-Extensions: permessage-deflate\r\n\r\n",
            ),
        ),
        (
            "empty extension",
            valid.replace("\r\n\r\n", "\r\nsec-websocket-extensions:\r\n\r\n"),
        ),
        (
            "wrong status",
            valid.replace("101 Switching Protocols", "200 OK"),
        ),
        ("HTTP 1.0", valid.replace("HTTP/1.1", "HTTP/1.0")),
        (
            "missing Connection",
            valid.replace("Connection: Upgrade\r\n", ""),
        ),
        (
            "missing Upgrade token",
            valid.replace("Connection: Upgrade", "Connection: keep-alive, xupgrade"),
        ),
        (
            "invalid Connection token",
            valid.replace("Connection: Upgrade", "Connection: Upgrade, bad token"),
        ),
        (
            "wrong Upgrade",
            valid.replace("Upgrade: websocket", "Upgrade: h2c"),
        ),
        (
            "duplicate Upgrade",
            valid.replace(
                "Upgrade: websocket",
                "Upgrade: websocket\r\nUpgrade: websocket",
            ),
        ),
        ("wrong accept", valid.replace("ACCEPT_KEY", "wrong-key")),
        (
            "duplicate accept",
            valid.replace(
                "Sec-WebSocket-Accept: ACCEPT_KEY",
                "Sec-WebSocket-Accept: ACCEPT_KEY\r\nSec-WebSocket-Accept: ACCEPT_KEY",
            ),
        ),
        (
            "missing accept",
            valid.replace("Sec-WebSocket-Accept: ACCEPT_KEY\r\n", ""),
        ),
        (
            "duplicate subprotocol",
            valid.replace(
                "Sec-WebSocket-Protocol: syntra.sc1.v1",
                "Sec-WebSocket-Protocol: syntra.sc1.v1\r\nSec-WebSocket-Protocol: syntra.sc1.v1",
            ),
        ),
        ("bare LF", valid.replace("\r\n", "\n")),
        ("truncated headers", valid[..valid.len() - 2].to_owned()),
        (
            "too many fields",
            valid.replace(
                "\r\n\r\n",
                &format!("\r\n{}\r\n", "X-Extra: a\r\n".repeat(65)),
            ),
        ),
        (
            "oversized complete headers",
            valid.replace(
                "\r\n\r\n",
                &format!("\r\nX-Pad: {}\r\n\r\n", "x".repeat(16 * 1024)),
            ),
        ),
        (
            "oversized incomplete headers",
            format!(
                "HTTP/1.1 101 Switching Protocols\r\nX-Pad: {}",
                "x".repeat(16 * 1024)
            ),
        ),
    ];
    for (label, response) in cases.drain(..) {
        let (listener, url) = listener().await;
        let (client, _) = configs(Mode::Returning);
        let task = tokio::spawn(async move {
            let (mut tls, accept) = raw_upgrade_peer(listener).await;
            let response = response.replace("ACCEPT_KEY", &accept);
            // A bounded early rejection may close before the oversized write finishes.
            let _ = tls.write_all(response.as_bytes()).await;
            let _ = tls.shutdown().await;
            let mut byte = [0];
            let next = tokio::time::timeout(Duration::from_secs(2), tls.read(&mut byte))
                .await
                .expect("client must close after invalid Upgrade");
            assert!(!matches!(next, Ok(n) if n > 0), "M1 leaked: {label}");
        });
        let result = dial(&url, client).await;
        if label == "truncated headers" {
            // Peer closed before completing headers: socket failure, not validation.
            assert!(matches!(result, Err(Error::Closed)), "{label}");
        } else {
            assert!(matches!(result, Err(Error::Configuration)), "{label}");
        }
        task.await.unwrap();
    }
}

#[tokio::test]
async fn untrusted_certificate_and_wrong_hostname_fail_before_sc1() {
    for wrong_host in [false, true] {
        let (listener, mut url) = listener().await;
        let (client, server) = configs(Mode::Bootstrap);
        let calls = Arc::new(AtomicUsize::new(0));
        let task = serve(listener, server, calls.clone());
        // A different generated root proves rejection of an actual untrusted
        // certificate rather than rejection of an empty configuration.
        let roots = if wrong_host {
            url = url.replace("127.0.0.1", "localhost");
            certificate().roots()
        } else {
            let other = rcgen::generate_simple_self_signed(vec!["127.0.0.1".into()]).unwrap();
            let mut roots = rustls::RootCertStore::empty();
            roots.add(other.cert.der().clone()).unwrap();
            roots
        };
        let result = ws::connect_with_roots(
            &url,
            roots,
            client,
            CREDENTIAL.to_vec(),
            ConnectionConfig::default(),
            limits(),
        )
        .await;
        assert!(matches!(result, Err(Error::Configuration)));
        assert!(task.await.unwrap().is_err());
        assert_eq!(calls.load(Ordering::SeqCst), 0);
    }
}

#[tokio::test]
async fn native_roots_do_not_trust_local_fixture() {
    let (listener, url) = listener().await;
    let (client, server) = configs(Mode::Bootstrap);
    let task = serve(listener, server, Arc::new(AtomicUsize::new(0)));
    let result = ws::connect(
        &url,
        client,
        CREDENTIAL.to_vec(),
        ConnectionConfig::default(),
        limits(),
    )
    .await;
    assert!(matches!(result, Err(Error::Configuration)));
    // A host with no native roots rejects before opening a socket.
    task.abort();
    let _ = task.await;
}

#[tokio::test]
async fn tls12_only_server_is_rejected_without_upgrade() {
    let (listener, url) = listener().await;
    let (client, _) = configs(Mode::Bootstrap);
    let task = tokio::spawn(async move {
        let (stream, _) = listener.accept().await.unwrap();
        tokio_rustls::TlsAcceptor::from(Arc::new(
            certificate().server_config(&rustls::version::TLS12),
        ))
        .accept(stream)
        .await
        .is_err()
    });
    assert!(matches!(
        dial(&url, client).await,
        Err(Error::Configuration)
    ));
    assert!(task.await.unwrap());
}

fn tls_client(version: &'static rustls::SupportedProtocolVersion) -> tokio_rustls::TlsConnector {
    let config = rustls::ClientConfig::builder_with_provider(Arc::new(
        rustls::crypto::ring::default_provider(),
    ))
    .with_protocol_versions(&[version])
    .unwrap()
    .with_root_certificates(certificate().roots())
    .with_no_client_auth();
    tokio_rustls::TlsConnector::from(Arc::new(config))
}

#[tokio::test]
async fn wss_server_rejects_tls12_client_before_authentication() {
    let (listener, url) = listener().await;
    let (_, server) = configs(Mode::Bootstrap);
    let calls = Arc::new(AtomicUsize::new(0));
    let task = serve(listener, server, calls.clone());
    let parsed = url::Url::parse(&url).unwrap();
    let stream = tokio::net::TcpStream::connect(("127.0.0.1", parsed.port().unwrap()))
        .await
        .unwrap();
    assert!(tls_client(&rustls::version::TLS12)
        .connect(ServerName::try_from("127.0.0.1").unwrap(), stream)
        .await
        .is_err());
    assert!(matches!(task.await.unwrap(), Err(Error::Configuration)));
    assert_eq!(calls.load(Ordering::SeqCst), 0);
}

#[tokio::test]
async fn wrong_noise_pin_is_rejected_before_authentication() {
    for mode in [Mode::Bootstrap, Mode::Returning] {
        let (listener, url) = listener().await;
        let (mut client, server) = configs(mode);
        client.server_public_key = generate_server_key().unwrap().1;
        let calls = Arc::new(AtomicUsize::new(0));
        let task = serve(listener, server, calls.clone());
        // NK authenticates the responder while processing M1; a wrong pin can
        // prevent even M2 from being produced. No hello reaches the factory.
        assert!(dial(&url, client).await.is_err());
        assert!(matches!(task.await.unwrap(), Err(Error::Channel(_))));
        assert_eq!(calls.load(Ordering::SeqCst), 0);
    }
}

#[tokio::test]
async fn unconfirmed_m2_never_releases_hello_or_credential() {
    let (listener, url) = listener().await;
    let (client, server) = configs(Mode::Returning);
    let task = tokio::spawn(async move {
        let (stream, _) = listener.accept().await.unwrap();
        let stream = tokio_rustls::TlsAcceptor::from(Arc::new(
            certificate().server_config(&rustls::version::TLS13),
        ))
        .accept(stream)
        .await
        .unwrap();
        let mut socket = tokio_tungstenite::accept_hdr_async(
            stream,
            |_: &_, mut response: tokio_tungstenite::tungstenite::handshake::server::Response| {
                response.headers_mut().insert(
                    "sec-websocket-protocol",
                    HeaderValue::from_static(ws::SUBPROTOCOL),
                );
                Ok(response)
            },
        )
        .await
        .unwrap();
        let Message::Binary(first) = socket.next().await.unwrap().unwrap() else {
            panic!("expected M1")
        };
        let (_, second) = syntra_secure_channel::respond(&server, &first).unwrap();
        // Even a server that could produce valid M2 gets no hello before M2.
        assert!(
            tokio::time::timeout(Duration::from_millis(100), socket.next())
                .await
                .is_err()
        );
        let mut tampered = second;
        *tampered.last_mut().unwrap() ^= 1;
        socket.send(Message::Binary(tampered.into())).await.unwrap();
        let next = tokio::time::timeout(Duration::from_secs(2), socket.next())
            .await
            .unwrap();
        assert!(!matches!(
            next,
            Some(Ok(Message::Binary(_) | Message::Text(_)))
        ));
    });
    assert!(matches!(dial(&url, client).await, Err(Error::Channel(_))));
    task.await.unwrap();
}

